    for ch in x:
        u = M[int(ch)]
        row = []
        for q in range(10):
            v = M[q]
            da, dr = bin(v & ~u).count("1"), bin(u & ~v).count("1")
            if da <= n and dr <= n:
                row.append((q, da, dr))
        o.append(row)
    return o


def _back(o, n, k):
    b = [set() for _ in range(k + 1)]
    b[k] = {(n, n)}
    for i in range(k - 1, -1, -1):
        s = set()
        for q, da, dr in o[i]:
            for a, r in b[i + 1]:
                if a - da >= 0 and r - dr >= 0:
                    s.add((a - da, r - dr))
        b[i] = s
    return b


def _walk(o, b, n, k, i, a, r, acc, rnd):
    """Yield every valid answer, in a random order, pruned by the backward table."""
    if i == k:
        if (a, r) == (n, n):
            yield "".join(acc)
        return
    row = list(o[i])
    rnd.shuffle(row)
    for q, da, dr in row:
        if (a + da, r + dr) in b[i + 1]:
            acc.append(str(q))
            for y in _walk(o, b, n, k, i + 1, a + da, r + dr, acc, rnd):
                yield y
            acc.pop()


def _find(x, n, rnd, limit):
    """A valid answer that is not merely a rearrangement of the clue's digits."""
    M = [63, 6, 91, 79, 102, 109, 125, 7, 127, 111]
    k = len(x)
    o = _opts(x, n, M)
    b = _back(o, n, k)
    if (0, 0) not in b[0]:
        return ""
    sx = sorted(x)
    c = 0
    for y in _walk(o, b, n, k, 0, 0, 0, [], rnd):
        if sorted(y) != sx:
            return y
        c += 1
        if c > limit:
            break
    return ""


def generate(seed):
    r = random.Random(seed)
    while True:
        k = r.choice([3, 3, 4, 4, 4, 5, 5, 6])
        n = r.choice([1, 2, 2, 2, 3, 3, 4])
        x = "".join(r.choice("0123456789") for _ in range(k))
        if _find(x, n, r, 4000):
            return x + "/" + str(n)

