def solve(clue):
    """Move exactly n segments off and n segments on, over the whole display, turning the
    clue's number into a different number of the same length (not a rearrangement of it).
    The answer is drawn at random from all valid ones, so successive demos differ in which
    digits move and in how the budget is spread."""
    x, n = clue.split("/")
    return _find(x, int(n), random.Random(clue), 4000)

